def esc(x):
 s=str(x).replace('not_extracted','not extracted').replace('\u2011','-').replace('\u2013','-').replace('\u2014','; ').replace('×','x').replace('µ','micro').replace('σ','sigma').replace('≤','<=').replace('≥','>=')
 return ''.join({'&':r'\&','%':r'\%','$':r'\$','#':r'\#','_':r'\_\allowbreak{}','/':r'/\allowbreak{}',':':r':\allowbreak{}','{':r'\{','}':r'\}','~':r'\textasciitilde{}','^':r'\textasciicircum{}','\\':r'\textbackslash{}'}.get(x,x) for x in s)
def para(s):return esc(s)+'\n\n'
def table(headers,rows,widths):
 spec=''.join(r'>{\raggedright\arraybackslash}p{'+str(w)+r'\linewidth}' for w in widths)
 return '\n{\\small\\begin{longtable}{'+spec+'}\n\\toprule\n'+' & '.join(map(esc,headers))+r'\\\midrule'+'\n\\endhead\n'+'\n'.join(' & '.join(map(esc,row))+r'\\' for row in rows)+'\n\\bottomrule\n\\end{longtable}}\n'
def sec(n,t):return '\n\\section{'+esc(t)+'}\n'
